import{_ as t,o as n,c as s,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"NEST: Narrative Event Structures in Time for Long Video Understanding","description":"","frontmatter":{"title":"NEST: Narrative Event Structures in Time for Long Video Understanding","arxiv":"2606.19706","date":"2026-06-18","authors":"Ali Asgarov, Kaushik Narasimhan, Najibul Haque Sarker, Hani Alomari, Chia-Wei Tang, Anushka Sivakumar, Zaber Ibn Abdul Hakim, Shaurya Mallampati, Chris Thomas","categories":"cs.CL, cs.CV","topics":"叙事事件, 长视频基准, 事件关系抽取","outline":[2,2]},"headers":[],"relativePath":"papers/2606.19706.md","filePath":"papers/2606.19706.md","lastUpdated":null}'),e={name:"papers/2606.19706.md"};function o(i,a,p,l,g,d){return n(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="nest-narrative-event-structures-in-time-for-long-video-understanding" tabindex="-1">NEST: Narrative Event Structures in Time for Long Video Understanding <a class="header-anchor" href="#nest-narrative-event-structures-in-time-for-long-video-understanding" aria-label="Permalink to &quot;NEST: Narrative Event Structures in Time for Long Video Understanding&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.19706" target="_blank" rel="noreferrer">2606.19706</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-18</td></tr><tr><td><strong>作者</strong></td><td>Ali Asgarov, Kaushik Narasimhan, Najibul Haque Sarker, Hani Alomari, Chia-Wei Tang, Anushka Sivakumar, Zaber Ibn Abdul Hakim, Shaurya Mallampati, Chris Thomas</td></tr><tr><td><strong>分类</strong></td><td>cs.CL, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 1005 部完整电影的音频描述轨为事件源，按 PropBank 体系标出每部平均 102 个叙事事件及其时序/因果/层级/共指关系，切成触发词检测、事件定位、论元抽取、关系抽取四项任务，把「长上下文能力」与「叙事理解能力」拆开来测。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/e-print/2606.19706</code> 取回的 LaTeX 源码（单文件，含正文、附录与全部表格）撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视觉语言模型现在能吞下很长的 token 流，但<strong>能处理长序列不等于理解叙事结构</strong>。这句话是全文的立论点，也是它与其他长视频基准的分界线。</p><p>现有长视频基准的主流形态是 needle-in-a-haystack 式检索：把一个答案埋在长视频某处，看模型能不能捞出来。这类题目测的是长上下文的寻址能力。叙事理解要问的是另一类问题：低层动作如何组成事件，事件如何跨时间互相作用，故事如何推进。论文给的例子很具体——模型能否把主角早期的失业与后期的分手连起来，尽管两者间隔很长、中间插了大量场景、还有闪回把已发生的事重新定义了一遍。</p><p>这件事重要，是因为「长上下文」和「叙事结构」这两种能力在现有评测里被混在一起了。如果一个模型在 needle 类基准上分数很高，我们无法据此判断它是否真的读懂了故事。NEST 的价值在于把这两条轴分开，并且提供了一组低到不可能靠答题技巧刷上去的分数。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频事件抽取</strong>这条线（VidSitu、Grounded VidSitu）源自 ImSitu 的图像结构化表示，同样采用 PropBank 体系，但操作对象是 2 到 10 秒的短片段。表 3 把规模差异摊开：VidSitu / GVSR 有 29,200 个视频、平均 10 秒、每视频 6.58 个事件、事件间平均时间距离 3.2 秒；VidEvent 有 1,110 个视频、平均 82 秒、21.61 个事件、时间距离 6.2 秒；NEST 是 1,005 个视频、平均 5,872.2 秒、102 个事件、每视频 5,100 对关系、<strong>事件间平均时间距离 1,920 秒</strong>。三个数量级的跨度决定了这不是同一个问题的放大版。MovieGraphs 标注了电影片段里的人际情境图，但同样只覆盖短场景，不覆盖完整叙事弧。</p><p><strong>长视频基准</strong>这条线的问题在表 1 里有系统对比：CinePile 平均 2.67 分钟、EgoSchema 3 分钟、LongVideoBench 7.89 分钟、Neptune 不超过 15 分钟、Video-MME (Long) 39.76 分钟、HourVideo 45.70 分钟、LVBench 68.35 分钟、MF² 88.33 分钟，NEST 是 97.87 分钟、总时长 1,639.3 小时。更要紧的是评测形式：这些基准大多用多选题，而多选题带有已被记录的选项位置偏置与选项数量陷阱，论文明确引用了这两条文献。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一个约束是标注成本。一部两小时的电影要标 100 个事件、每个事件的论元、以及事件之间的关系，靠人力标 1000 部是不现实的（论文实测 5 部 GOLD 电影花了约 600 美元人力费）。所以必须找一个高质量的、已经存在的、与画面对齐的文本源。</p><p><strong>音频描述（AD）轨</strong>正好符合。AD 是专业人员为视障观众写的画面旁白，天然是对视觉内容的忠实叙述，且与时间轴对齐。已有的 AutoAD 系列工作已经确立了 AD 作为高质量视觉叙述源的地位。用 Whisper 转写 AudioVault 的 AD 轨，再用 LLM 修错与对齐，就得到了一份逐场景的画面文本。</p><p>第二个约束是事件的定义要可复现。自由文本描述无法评测，所以借 VidSitu 的做法，把触发词限定在 PropBank 的谓词集合内，论元限定在 ARG0/ARG1 与 ARGM-LOC/ARGM-TMP 这类标准角色上。</p><p>第三个约束是时间定位。理想情况是给每个事件精确的起止时刻，但作者做了一个诚实的探路实验（附录表 8）：在 VidEvent 的短视频上，Gemini 2.5 Pro 的 mIoU 只有 7.96，Time-R1 是 23.23。既然连几分钟的视频都定位不准，在两小时电影上强求帧级边界没有意义。于是退而求其次，用包含该事件的<strong>场景边界</strong>作为其时间范围，这是一个高召回的保守回退。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>叙事理解可以拆成两件性质完全不同的事：<strong>从原始影像里发现并锚定事件</strong>，以及<strong>在已给定的事件之间做推理</strong>。把它们混在一道多选题里，模型可以靠后者的部分能力遮掩前者的彻底失败。分开测之后结论立刻清晰——关系分类给了事件就还行，发现事件本身几乎为零。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据来源</strong>：在 MovieNet、MovieQA 之外，从 Library of Congress、archive.org、PublicDomainMovies、YouTube 等处收集了至少一小时长的开放域视频。元数据（剧情梗概、synopsis、剧本）来自 IMDb、Wikipedia、OpenSubtitles。AD 轨来自 AudioVault，用 Whisper 转写后由 LLM 修正与对齐。共指用 Maverick 加 LLM 方法，给每个实体分配全局唯一标识。场景切分用 PySceneDetect。</p><p><strong>四类标注</strong>：</p><ul><li><strong>触发词</strong>：OmniEvent 做开放域检测，再叠加受限于 PropBank 谓词集的 LLM 抽取。</li><li><strong>论元</strong>：LLM 做语义角色抽取，辅以 GLEN 与 OmniEvent 的预测，全部遵循 PropBank 约定。</li><li><strong>关系</strong>：时序（before / after / overlap）、因果、层级、共指，用文档级事件抽取那一路的文本方法由 LLM 抽出。</li><li><strong>时间定位</strong>：先用 Time-R1 与 Gemini 2.5 Pro 做时序定位，失败时回退到场景边界。</li></ul><p><strong>两级标注集</strong>：SILVER 覆盖全部 1,005 部电影，由 Grok-4.1 Fast 驱动的流水线生成，消耗约 1,000 亿 token，用剧情梗概与 AD 双重交叉验证；GOLD 是 5 部电影的全人工标注，每部约 70 个事件、50 对关系，由 5 名签约标注员在自建平台上完成，时薪 15 美元，总计约 600 美元。一致性用加权 Cohen&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 与平均语义相似度衡量：GOLD 内两名标注员之间约 0.57，GOLD 与 SILVER 之间约 0.50，即自动流水线达到人–人一致性的约 86–88%。</p><p><strong>四项任务</strong>：</p><ul><li><strong>ETD</strong>：给定视频与场景边界，预测该场景的叙事事件触发动词与上下文，要求的是故事层面的动作而非表层动作。</li><li><strong>EL</strong>：给定事件描述，预测其时间边界，按是否落在 ground-truth 场景内判定。每部电影约 160.61 个场景，因此随机猜测的下限约 0.6%。</li><li><strong>EAE</strong>：给定触发词与语义角色，填出论元值。</li><li><strong>ERE</strong>：给定一对事件，从 {时序, 因果, 前置, 层级, 共指, 无关系} 六类中预测关系，直接算 P/R/F1，无需 judge。闪回子集单列。</li></ul><p><strong>评测方式</strong>：ERE 是闭集，直接算 F1；EL 用时间重叠自动判定；ETD 与 EAE 是开放式输出，「fight」对上 ground-truth 的「attack」应算对，同一角色可能被称作「the detective」或「Officer Miller」，因此用 LLM-as-a-judge 判语义等价。</p><p><strong>微调基线</strong>：Qwen3-Omni-30B-A3B-Instruct，8 张 NVIDIA H200，混合精度，冻结视觉编码器与多模态对齐层，语言模型部分走 LoRA；因为电影长 2 到 3 小时且视觉冗余极高，视频输入按 <strong>0.1 FPS</strong> 稀疏采样，配合 gradient checkpointing 与 FlashAttention 支撑长序列。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：低分是任务难，还是评测坏了？</strong> 论文专门给了随机水位作对照，这一点做得比多数基准论文扎实。EL 是从约 160 个场景里选一个，随机下限约 0.6%，最好的零样本模型（Qwen3-VL 30B）是 5.89%，约 9 倍随机。ETD 与 EAE 在一个宽容的、接受同义改写的 LLM judge 下评分，最好成绩仍分别低于 8% 与 11%。而同一套流水线下 ERE 能到 35.45% F1，说明不是解析或 judge 把所有分数一起压塌了。</p><p><strong>问题二：发现事件有多难？</strong> 表 4（14 个模型）里 ETD 最好是 LLaVA-Video 的 7.98%，EL 最好是 Qwen3-VL 30B 的 5.89%，EAE 最好是 OVIS2.5 的 10.62%。论文强调<strong>增加帧数并没有帮助</strong>——瓶颈在叙事抽象与时间锚定，不在视觉覆盖。错误分类（附录）给出了失败的形状：ETD 的错误 78% 是给出了错误的叙事事件、22% 是退回了表层原子动词；EL 的错误 98.6% 是选错场景；EAE 的错误 90% 是实体混淆。图 3 的例子里 Qwen3-VL (8B) 把攻击者答成了「Christian Bale」——把预训练里的演员知识注入到了应当描述画面内容的位置；InternVL3.5 则把攻击者与受害者的角色对调了。</p><p><strong>问题三：给定事件后推理呢？</strong> 零样本 ERE 最高 35.45% F1（Qwen2.5-VL 32B），微调后的 Qwen3-Omni 到 44.42% F1。闭源模型另测（表 5，仅 10 部电影，API 成本约 500 美元）：GPT-5 是 40.80% F1，Gemini 2.5 Pro 是 21.09%。</p><p><strong>问题四：微调改善了什么？</strong> 结论很干净：微调大幅改善 ERE（35.45 → 44.42），但没有带来 ETD/EL 的对应提升——微调后 ETD 是 6.09、EL 是 <strong>0.45</strong>（比零样本最好的 5.89 还低一个数量级）。论文的解释是 ERE 是给定两个事件的闭集条件推理，模型只需学一个判别规则；ETD/EL 要求在整部电影里搜索、从低层多模态证据里抽出故事层面的抽象、再锚定到约 160 个候选场景中的正确一个。附录的训练曲线佐证了这点：ERE 的 loss 稳定下降，ETD 与 EL 的 loss 很早就平了。</p><p><strong>问题五：非线性时间结构呢？</strong> 闪回子集上七个模型里五个拿到 0.00 F1，只有 Qwen2.5-VL (32B) 有 28.57%。包括 InternVL3.5 (30B) 与两个 Qwen3-VL 变体在内的较大模型完全失败，尽管它们在一般 ERE 上并不差。</p><p><strong>问题六：纯文本能绕过去吗？</strong> 表 6 用 Gemini 2.5 Pro 为每个场景生成 caption 后做纯文本事件抽取，F1@5 只有 5.23，反而低于纯文本 EE 方法 GLEN 的 8.2 与 OmniEvent 的 6.0/6.3。这条对照说明这个任务不能靠语言先验绕过视频。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：把「长上下文能力」与「叙事理解能力」分开测，是 NEST 相对已有长视频基准最重要的方法论贡献；分开之后的结论是发现事件几乎完全没解决（ETD &lt; 8%、EL &lt; 6%、EAE &lt; 11%），而给定事件后的关系分类相对可做（零样本 35.45% F1、微调后 44.42%）；微调只提升后者不提升前者，这个分离本身就是一个可复用的诊断；闪回这类非线性时间结构是灾难性的失败点，七个模型里五个拿 0.00 F1；标注体系值得借鉴——每部 102 个事件（68 视觉 + 31 对白 + 3 音效）、AD 作为事件源、PropBank 约束触发词与论元、场景级定位作为保守回退。</p><p><strong>3 句话版</strong>：1005 部完整电影、每部 102 个多模态叙事事件、四项结构化任务，把长视频评测从大海捞针换成事件图的构建与推理。当前模型能在给定事件时分类关系，但几乎无法从原始影像里发现并锚定事件。想做叙事级评测的人应该先看它的事件定义与标注协议，不要重造。</p><p><strong>1 句话版</strong>：一个把「读得完」和「读得懂」分开来测的长视频叙事基准，结果是后者基本没开始。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>失败代价最大的一条是：<strong>音频描述转写出来的文本事件，等同于视频里「真实发生的叙事事件」</strong>。整个 ground truth 的来源是这一条链——AD 轨 → Whisper 转写 → LLM 修正 → LLM 抽触发词与论元 → LLM 抽关系。视频本身从未直接进入标注环路，它只在最后的时间定位环节被用到，而那一步还常常回退到场景边界。</p><p>这个假设在两个方向上都可能不成立。AD 是为<strong>视障听众</strong>写的，它选择叙述什么、省略什么，服从的是「听不见画面的人需要知道什么」这个特定目的，而不是「这段影像里发生了什么叙事事件」的中立枚举——服装、构图、微表情、纯视觉的伏笔往往不被叙述，而角色的进出场、位置移动这类便于口述的信息会被过度叙述。反方向上，模型如果正确描述了一个 AD 没有旁白的真实事件，会被判为错误。</p><p>结果是：ETD 那个「低于 8%」的数字，测的可能有相当一部分是「模型能否猜中这条 LLM 流水线从 AD 文本里挑出的那个 PropBank 谓词」。论文自己在 Limitations 里承认了标注流水线用 LLM 验证可能引入偏差，也承认 LLM judge 会带入自身的叙事理解局限，这是诚实的。</p><p>论文为这个假设提供的证据是标注一致性：GOLD 内人–人加权 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.57</span></span></span></span>，GOLD–SILVER <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.50</span></span></span></span>。这两个数字有用，但它们衡量的是<strong>标注协议的可复现性</strong>，不是<strong>标注与视频内容的一致性</strong>——两名标注员看着同一份 AD 与剧情梗概，达成 0.57 的一致，不能推出这份事件清单覆盖了影片里发生的事。而且 0.57 的人–人一致性本身并不高，它意味着即使是人也只在略超一半的判断上互相同意，这为「模型得分低」提供了一个与「任务难」并列的替代解释。</p><p>真正缺的证据是<strong>人类在任务上的表现</strong>（不是标注一致性）。如果让一名没参与标注的人看完整部电影去做 ETD，他能拿多少？这个上限没有报，因此我们无法判断 7.98% 距离可达的天花板是很远还是不算太远。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现整个基准，一周内可做一个针对 §9 的关键诊断：</p><ol><li>取 GOLD 的 5 部电影，构造一个「特权文本」基线：<strong>直接把该场景的 AD 转写文本喂给一个强 LLM</strong>（不给视频），让它做 ETD 与 EAE，用同一个 LLM judge 评分。</li><li>对照点是表 4 里的视频模型成绩（ETD 最好 7.98、EAE 最好 10.62）和表 6 里用 Gemini caption 的纯文本成绩（F1@5 = 5.23）。</li><li>判据：若 AD 特权基线拿到 70% 以上，说明这些任务在给定正确文本叙述时是容易的，视频模型那 8% 主要测的是「视频 → AD 级叙述」这一段能力差距，而不是叙事结构理解本身；若 AD 特权基线也只有 20–30%，那么难点确实在从叙述到 PropBank 结构的抽象上，与模态无关，视频模型的低分就得到了另一种解释。</li></ol><p>论文明确说把 AD 当作「特权模态」而刻意不用它做基线（理由是 AD 并非所有视频都有）。理由成立，但这恰恰意味着这个最有诊断价值的对照被主动放弃了——它不需要作为公平基线出现在主表里，只需要作为一个 sanity check 出现在附录里。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>第一击针对<strong>微调后 ERE 那个 44.42% 的构成</strong>。拆开表 4 的最后一行：共指 <strong>100.00</strong>、层级 76.82、因果 62.12、前置 38.26、无关系 15.58、时序 <strong>2.44</strong>。这是六类的宏平均。一个类别恰好拿到 100.00 是极强的捷径信号——共指关系很可能可以从两个事件描述的表层字符串重合度直接判出来，根本不需要看视频。与此同时，无关系一项从零样本最好的 42.79 掉到 15.58，时序从最好的 14.29 掉到 2.44。也就是说微调把模型推向了「倾向于宣称存在关系」，宏平均被一个退化的满分类别抬起来了。反例实验：报告去掉共指类之后的五类宏平均，并单独报告共指的字符串重合度基线（把两个事件描述的词重叠率过一个阈值当作共指预测）。如果这个零成本基线在共指上也接近 100，那么 35.45 → 44.42 这个头条提升需要重新解读。</p><p>第二击针对 <strong>EL 的 ground truth 本身就是一个回退启发式</strong>。论文明说时序定位模型不可靠，所以「保守地」用包含该事件的场景边界当作它的时间范围。于是 EL 这个任务在问：你能不能选中 LLM 流水线当初把这条 AD 句子分配过去的那个场景。当一个事件横跨相邻两个场景、或者 AD 的旁白出现在事件发生之后（AD 常在对白间隙插入，时间上会滞后），正确答案本身就是错位的。98.6% 的错误是「选错场景」这一事实与之相容：它既可以解释成模型不会定位，也可以解释成标签有系统性偏移。可做的反例是把 EL 放宽到「预测场景与真值场景相邻即算对」，看分数从 5.89 跳到多少。如果跳到 20% 以上，说明相当一部分失败是 off-by-one 而不是完全找不到。</p><p>第三击是<strong>缺失的平凡基线</strong>。ERE 是六分类，论文没有报告「永远预测出现频率最高的那一类」的宏平均 F1，也没有报告类别分布。在一个每视频有 5,100 对关系的数据集里，无关系类几乎必然占绝对多数，多数类基线的宏 F1 虽然会很低，但它给出的是「不看视频、不看事件描述」的地板，是判断 21.09（Gemini 2.5 Pro）这类分数是否有意义的必要参照。同理，ETD 的触发词来自 PropBank 谓词集，「永远预测最高频的那个谓词」也应当有一个数字。这两个地板不给，ETD 的 7.98 与 ERE 的 21.09 就缺少一个下界锚点。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：NEST 的标注单元是<strong>场景内的事件</strong>。作者在 Limitations 里明确承认，那些只有跨场景联合推理才能发现的事件——角色的渐进转变、跨若干不相邻场景展开的支线——在当前标注里完全不存在。而这恰恰是叙事理解最核心的部分：一个人物弧线不是任何单个场景里的事件。</p><p><strong>新的 framing</strong>：把叙事理解从「抽取事件再连边」重述为「<strong>维护一个随时间演化的世界状态</strong>」。事件是状态转移的观测，而不是要抽取的实体本身。这个转向的好处是，跨场景的渐进变化在事件本体论里无法表达，但在状态轨迹里是自然的——它就是某个状态变量的缓慢漂移。</p><p><strong>可借鉴的邻域工具</strong>：文本领域的 entity state tracking 与 procedural text understanding（如 ProPara 那一路的「实体属性随步骤变化」标注），以及概率程序里的状态空间模型。NEST 已经有一份跨全片的统一实体表（共指阶段建的），这正是状态轨迹所需的骨架。</p><p><strong>第一个实验</strong>：在 GOLD 的 5 部电影上，为每个主要角色定义少量离散状态变量（例如 employment、relationship、location、知识状态），沿场景序列标出每个变量的取值与变化点，构成一条状态轨迹。然后设计两个探针：一是<strong>变化点检测</strong>——给定整部电影，预测某个变量在哪些场景发生了改变；二是<strong>状态查询</strong>——在第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 个场景处询问某变量的当前取值。判据在于这两个探针与 NEST 现有四项任务的相关性：如果一个模型在 ERE 上不错却在状态查询上很差，就证实了「关系分类是可以在不维护世界状态的情况下靠表层线索做出来的」，也就为「事件图不是叙事理解的充分表示」提供了直接证据。这个实验的规模是可控的，因为它复用现成的场景切分与实体表，只需增加一层轻量的状态标注。</p>',59)])])}const c=t(e,[["render",o]]);export{u as __pageData,c as default};
